<?php
defined( 'ABSPATH' ) || exit;

/**
 * Fresh-20 corrective hardening for the 2026-08-12 File 11 plan.
 *
 * This class intentionally stays additive: it tightens public-read, mutation,
 * privacy, concurrency and provider-boundary behavior without taking ownership
 * away from File 00/05/06/10/16/26.
 */
final class RSV_Fresh20_Hardening {
	const CONTRACT_VERSION = 1;
	const MIN_ANALYTICS     = 5;

	public static function boot() {
		add_action( 'plugins_loaded', array( __CLASS__, 'register' ), 90 );
	}

	public static function register() {
		add_filter( 'rest_request_before_callbacks', array( __CLASS__, 'before_callbacks' ), 5, 3 );
		add_filter( 'rest_post_dispatch', array( __CLASS__, 'after_dispatch' ), 99, 3 );
		remove_action( 'get_footer', array( 'RSV_Future30', 'single_reel_tools' ), 3 );
		add_action( 'get_footer', array( __CLASS__, 'safe_single_reel_tools' ), 3 );
		remove_shortcode( 'rsv_future30' );
		add_shortcode( 'rsv_future30', array( __CLASS__, 'shortcode' ) );
		add_action( 'wp_enqueue_scripts', array( __CLASS__, 'apply_feed_runtime_preferences' ), 50 );
	}

	public static function before_callbacks( $response, $handler, $request ) {
		unset( $handler );
		if ( null !== $response ) return $response;
		$route  = $request->get_route();
		$method = strtoupper( $request->get_method() );

		if ( 'POST' === $method && '/rsv/v1/future30/series' === $route ) return self::validate_series_request( $request );
		if ( 'POST' === $method && '/rsv/v1/future30/learning-paths' === $route ) return self::validate_learning_path_request( $request );

		if ( 'POST' === $method && preg_match( '#^/rsv/v1/reels/(reel_[a-f0-9-]{36})/future30/(F11-FUT-[0-9]{3})$#', $route, $m ) ) {
			$reel = RSV_Repository::find( $m[1], true );
			if ( ! $reel ) return $response;
			$validation = self::validate_feature_request( $m[2], $reel, (array) $request->get_json_params() );
			return is_wp_error( $validation ) ? $validation : $response;
		}

		if ( 'POST' === $method && preg_match( '#^/rsv/v1/reels/(reel_[a-f0-9-]{36})/quiz/attempt$#', $route ) ) return self::quiz_attempt( $request );
		if ( 'POST' === $method && '/rsv/v1/future30/collections' === $route ) return self::collection_write( $request );
		if ( 'POST' === $method && preg_match( '#^/rsv/v1/reels/(reel_[a-f0-9-]{36})/notes$#', $route ) ) return self::note_write( $request );
		if ( in_array( $method, array( 'POST', 'PUT', 'PATCH' ), true ) && '/rsv/v1/future30/feed-preferences' === $route ) return self::feed_preferences_write( $request );
		if ( in_array( $method, array( 'POST', 'PUT', 'PATCH' ), true ) && '/rsv/v1/future30/accessibility' === $route ) return self::accessibility_write( $request );
		return $response;
	}

	private static function validate_series_request( $request ) {
		$p     = (array) $request->get_json_params();
		$title = RSV_Helpers::text( $p['title'] ?? '', 255 );
		$refs  = array_values( array_unique( array_filter( array_map( 'sanitize_text_field', (array) ( $p['ordered_reels'] ?? array() ) ) ) ) );
		if ( '' === trim( $title ) || count( $refs ) < 1 || count( $refs ) > 100 ) return RSV_Helpers::error( 'rsv_series_invalid', __( 'A public Reel series needs a title and 1 to 100 current public Reels.', RSV_TEXT_DOMAIN ), 422 );
		foreach ( $refs as $ref ) if ( ! self::public_ref_valid( 'File 11', $ref, 'series-write' ) ) return RSV_Helpers::error( 'rsv_series_reel_invalid', __( 'Every series item must be a current public Reel.', RSV_TEXT_DOMAIN ), 422 );
		if ( isset( $p['difficulty'] ) && '' !== (string) $p['difficulty'] && ! in_array( sanitize_key( $p['difficulty'] ), array( 'beginner', 'intermediate', 'advanced' ), true ) ) return RSV_Helpers::error( 'rsv_series_difficulty_invalid', __( 'Series difficulty must be beginner, intermediate or advanced.', RSV_TEXT_DOMAIN ), 422 );
		return null;
	}

	private static function validate_learning_path_request( $request ) {
		$p         = (array) $request->get_json_params();
		$title     = RSV_Helpers::text( $p['title'] ?? '', 255 );
		$raw_steps = (array) ( $p['steps'] ?? array() );
		if ( '' === trim( $title ) || count( $raw_steps ) < 1 || count( $raw_steps ) > 100 ) return RSV_Helpers::error( 'rsv_learning_path_invalid', __( 'A learning path needs a title and 1 to 100 validated steps.', RSV_TEXT_DOMAIN ), 422 );
		foreach ( (array) ( $p['file05_course_refs'] ?? array() ) as $ref ) if ( true !== apply_filters( 'rsv_future30_file05_public_ref_valid', false, RSV_Helpers::text( $ref, 255 ) ) ) return RSV_Helpers::error( 'rsv_learning_ref_invalid', __( 'Every learning reference must be current and public according to File 05.', RSV_TEXT_DOMAIN ), 422 );
		foreach ( $raw_steps as $step ) {
			if ( ! is_array( $step ) ) return RSV_Helpers::error( 'rsv_learning_step_invalid', __( 'Every learning-path step must be structured data.', RSV_TEXT_DOMAIN ), 422 );
			$ref = RSV_Helpers::text( $step['file05_ref'] ?? '', 255 );
			if ( ! $ref || true !== apply_filters( 'rsv_future30_file05_public_ref_valid', false, $ref ) ) return RSV_Helpers::error( 'rsv_learning_ref_invalid', __( 'Every learning-path step must point to a current public File 05 course or lesson.', RSV_TEXT_DOMAIN ), 422 );
			if ( isset( $step['level'] ) && ! in_array( sanitize_key( $step['level'] ), array( 'beginner', 'intermediate', 'advanced' ), true ) ) return RSV_Helpers::error( 'rsv_learning_level_invalid', __( 'Every learning-path level must be beginner, intermediate or advanced.', RSV_TEXT_DOMAIN ), 422 );
		}
		return null;
	}

	private static function validate_feature_request( $feature, $reel, $p ) {
		switch ( $feature ) {
			case 'F11-FUT-005':
				$grade = sanitize_key( (string) ( $p['grade'] ?? '' ) );
				$allowed = array( 'primary', 'primary-source', 'classical', 'classical-text', 'clinical', 'clinical-observation', 'research', 'research-evidence', 'opinion', 'author-opinion', 'disputed' );
				if ( ! in_array( $grade, $allowed, true ) ) return RSV_Helpers::error( 'rsv_evidence_grade_invalid', __( 'Evidence grade must use an approved bounded classification.', RSV_TEXT_DOMAIN ), 422 );
				break;
			case 'F11-FUT-008':
				$source = RSV_Helpers::text( $p['source_reel_ref'] ?? '', 255 );
				if ( $source && hash_equals( (string) $reel['public_id'], $source ) ) return RSV_Helpers::error( 'rsv_remix_self_invalid', __( 'A Reel cannot be its own remix source.', RSV_TEXT_DOMAIN ), 409 );
				break;
			case 'F11-FUT-010':
				$type = sanitize_key( (string) ( $p['template_type'] ?? 'clinical-pearl' ) );
				if ( ! in_array( $type, array( 'remedy-in-3-minutes', 'clinical-pearl', 'book-quote', 'myth-evidence', 'question-answer', 'q-and-a' ), true ) ) return RSV_Helpers::error( 'rsv_template_type_invalid', __( 'Choose an approved Reel template type.', RSV_TEXT_DOMAIN ), 422 );
				$sections = (array) ( $p['sections'] ?? array() );
				if ( count( $sections ) > 12 ) return RSV_Helpers::error( 'rsv_template_sections_invalid', __( 'A Reel template may contain at most 12 bounded sections.', RSV_TEXT_DOMAIN ), 422 );
				foreach ( $sections as $section ) if ( ! is_array( $section ) || count( $section ) > 8 ) return RSV_Helpers::error( 'rsv_template_sections_invalid', __( 'Every Reel template section must be bounded structured data.', RSV_TEXT_DOMAIN ), 422 );
				$recipe = RSV_Helpers::text( $p['file10_media_recipe_ref'] ?? '', 255 );
				if ( $recipe && true !== apply_filters( 'rsv_future30_file10_media_recipe_ref_valid', false, $recipe, $reel, $type ) ) return RSV_Helpers::error( 'rsv_template_media_recipe_invalid', __( 'The File 10 media recipe reference is not current and valid.', RSV_TEXT_DOMAIN ), 422 );
				break;
			case 'F11-FUT-013':
				if ( 'approved' === sanitize_key( $p['decision'] ?? '' ) && ! empty( $p['conflict_declared'] ) ) return RSV_Helpers::error( 'rsv_peer_review_conflict', __( 'A reviewer who declares a conflict cannot issue the public approval badge for this Reel.', RSV_TEXT_DOMAIN ), 409 );
				break;
			case 'F11-FUT-014':
				$lang = str_replace( '_', '-', RSV_Helpers::text( $p['language'] ?? '', 20 ) );
				if ( ! preg_match( '/^[A-Za-z]{2,3}(?:-[A-Za-z0-9]{2,8})*$/', $lang ) ) return RSV_Helpers::error( 'rsv_language_invalid', __( 'Use a valid language tag for the linked Reel version.', RSV_TEXT_DOMAIN ), 422 );
				$linked = RSV_Helpers::text( $p['linked_reel_ref'] ?? '', 255 );
				if ( ! $linked || hash_equals( (string) $reel['public_id'], $linked ) || ! self::public_ref_valid( 'File 11', $linked, 'translated-reel-write' ) ) return RSV_Helpers::error( 'rsv_translated_reel_invalid', __( 'Every additional language must link to a different current public Reel.', RSV_TEXT_DOMAIN ), 422 );
				$linked_reel = RSV_Repository::find( $linked, true );
				$declared = strtolower( $lang );
				$actual   = strtolower( str_replace( '_', '-', (string) ( $linked_reel['language'] ?? '' ) ) );
				if ( ! $actual || ! hash_equals( $actual, $declared ) ) return RSV_Helpers::error( 'rsv_translation_language_mismatch', __( 'The linked Reel language does not match the declared language.', RSV_TEXT_DOMAIN ), 422 );
				$status = sanitize_key( $p['translation_status'] ?? 'candidate' );
				if ( ! in_array( $status, array( 'candidate', 'approved', 'published' ), true ) ) return RSV_Helpers::error( 'rsv_translation_status_invalid', __( 'Translation status must be candidate, approved or published.', RSV_TEXT_DOMAIN ), 422 );
				break;
			case 'F11-FUT-024':
				$allowed = array( 'topic-interest', 'followed-doctor', 'recent-learning', 'diversity', 'latest', 'search-match', 'series-continuity', 'learning-path', 'language-match' );
				$reasons = (array) ( $p['allowed_reasons'] ?? array() );
				if ( count( $reasons ) > 12 ) return RSV_Helpers::error( 'rsv_explanation_reason_invalid', __( 'Recommendation explanation reasons must stay bounded and non-commercial.', RSV_TEXT_DOMAIN ), 422 );
				foreach ( $reasons as $reason ) if ( ! in_array( sanitize_key( $reason ), $allowed, true ) ) return RSV_Helpers::error( 'rsv_explanation_reason_invalid', __( 'Recommendation explanation reasons must use approved non-commercial categories.', RSV_TEXT_DOMAIN ), 422 );
				break;
		}
		return true;
	}

	public static function after_dispatch( $response, $server, $request ) {
		unset( $server );
		if ( ! ( $response instanceof WP_REST_Response ) ) return $response;
		$route  = $request->get_route();
		$method = strtoupper( $request->get_method() );
		if ( 'GET' === $method && '/rsv/v1/future30/series' === $route ) return self::filter_series_response( $response );
		if ( 'GET' === $method && '/rsv/v1/future30/learning-paths' === $route ) return self::filter_learning_path_response( $response );
		if ( 'GET' === $method && preg_match( '#^/rsv/v1/reels/(reel_[a-f0-9-]{36})/future30/(F11-FUT-[0-9]{3})$#', $route, $m ) ) return self::filter_generic_feature_response( $response, $m[2], $m[1] );
		if ( 'GET' === $method && preg_match( '#^/rsv/v1/reels/(reel_[a-f0-9-]{36})/ai-context$#', $route, $m ) ) return self::filter_ai_context( $response, $m[1] );
		if ( 'GET' === $method && preg_match( '#^/rsv/v1/reels/(reel_[a-f0-9-]{36})/knowledge-graph$#', $route, $m ) ) return self::filter_knowledge_graph( $response, $m[1] );
		if ( 'GET' === $method && preg_match( '#^/rsv/v1/reels/(reel_[a-f0-9-]{36})/why$#', $route ) ) return self::filter_why_response( $response );
		if ( 'GET' === $method && '/rsv/v1/future30/feed-preferences' === $route ) return self::filter_feed_preferences_response( $response );
		return $response;
	}

	private static function filter_series_response( $response ) {
		$data = $response->get_data();
		if ( ! is_array( $data ) ) return $response;
		$out = array();
		foreach ( $data as $row ) {
			if ( ! is_array( $row ) ) continue;
			$refs = array_values( array_filter( array_map( 'sanitize_text_field', (array) ( $row['payload']['ordered_reels'] ?? array() ) ) ) );
			if ( ! $refs ) continue;
			$valid = true;
			foreach ( $refs as $ref ) if ( ! self::public_ref_valid( 'File 11', $ref, 'series-public-read' ) ) { $valid = false; break; }
			if ( ! $valid ) continue;
			unset( $row['owner_id'], $row['reel_id'], $row['id'] );
			$row['payload'] = array( 'description'=>RSV_Helpers::textarea($row['payload']['description']??'',2000), 'difficulty'=>RSV_Helpers::enum($row['payload']['difficulty']??'',array('beginner','intermediate','advanced'),''), 'ordered_reels'=>$refs );
			$out[] = $row;
		}
		$response->set_data( $out );
		return $response;
	}

