		$data = $response->get_data(); if ( ! is_array( $data ) ) return $response; $out=array();
		foreach($data as $row){if(!is_array($row))continue;$steps=array();$valid=true;foreach((array)($row['payload']['steps']??array())as$step){if(!is_array($step)){$valid=false;break;}$ref=RSV_Helpers::text($step['file05_ref']??'',255);if(!$ref||true!==apply_filters('rsv_future30_file05_public_ref_valid',false,$ref)){$valid=false;break;}$steps[]=array('title'=>RSV_Helpers::text($step['title']??'',255),'level'=>RSV_Helpers::enum($step['level']??'beginner',array('beginner','intermediate','advanced'),'beginner'),'file05_ref'=>$ref,'summary'=>RSV_Helpers::textarea($step['summary']??'',1200));}if(!$valid||!$steps)continue;$refs=array_values(array_filter(array_map('sanitize_text_field',(array)($row['payload']['file05_course_refs']??array()))));foreach($refs as$ref)if(true!==apply_filters('rsv_future30_file05_public_ref_valid',false,$ref)){$valid=false;break;}if(!$valid)continue;unset($row['owner_id'],$row['reel_id'],$row['id']);$row['payload']=array('level'=>RSV_Helpers::enum($row['payload']['level']??'beginner',array('beginner','intermediate','advanced'),'beginner'),'description'=>RSV_Helpers::textarea($row['payload']['description']??'',2000),'steps'=>$steps,'file05_course_refs'=>$refs);$out[]=$row;}
		$response->set_data($out);return$response;
	}

