		if('F11-FUT-010'===$feature){$types=array('remedy-in-3-minutes','clinical-pearl','book-quote','myth-evidence','question-answer','q-and-a');$objects=array();foreach((array)($data['objects']??array())as$row){if(!is_array($row)||!in_array(sanitize_key($row['payload']['template_type']??'clinical-pearl'),$types,true))continue;$recipe=RSV_Helpers::text($row['payload']['file10_media_recipe_ref']??'',255);if($recipe&&true!==apply_filters('rsv_future30_file10_media_recipe_ref_valid',false,$recipe,$reel,sanitize_key($row['payload']['template_type']??'clinical-pearl')))continue;$objects[]=$row;}$data['objects']=$objects;}
