	}

	private static function answer_correct( $question, $answer ) {
		$type=sanitize_key($question['type']??'single-choice');if('multiple-choice'===$type){$expected=array_values(array_unique(array_map(static function($v){return RSV_Helpers::text($v,500);},(array)($question['correct']??array()))));$actual=array_values(array_unique(array_map(static function($v){return RSV_Helpers::text($v,500);},(array)$answer)));sort($expected,SORT_STRING);sort($actual,SORT_STRING);return$expected===$actual;}if('true-false'===$type)return self::normalize_bool_answer($question['correct']??'')===self::normalize_bool_answer($answer);$expected=is_array($question['correct']??null)?reset($question['correct']):($question['correct']??'');$actual=is_array($answer)?reset($answer):$answer;return hash_equals(RSV_Helpers::text($expected,500),RSV_Helpers::text($actual,500));
	}

	private static function normalize_bool_answer( $value ) {$value=strtolower(trim((string)$value));if(in_array($value,array('1','true','yes'),true))return'true';if(in_array($value,array('0','false','no'),true))return'false';return'invalid';}

