	public static function apply_feed_runtime_preferences() {if(!is_user_logged_in()||!wp_script_is('rsv','registered'))return;$prefs=self::future_user_payload(get_current_user_id(),'F11-FUT-025','user','feed_preferences',array('autoplay'=>false));if(empty($prefs['autoplay']))return;wp_enqueue_script('rsv');$js="(function(){function apply(){var b=document.querySelector('[data-rsv-autoplay]');if(b&&b.getAttribute('aria-pressed')!=='true'){b.click();}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply);else apply();})();";wp_add_inline_script('rsv',$js,'after');}
