	public static function shortcode( $atts ) {$atts=shortcode_atts(array('reel'=>''),$atts,'rsv_future30');$reel=RSV_Repository::find(RSV_Helpers::text($atts['reel'],80),true);if(!$reel||!RSV_Security::can_view_reel($reel))return'';return self::render_safe_tools($reel);}

	private static function render_safe_tools( $reel ) {$citations=self::safe_edges('F11-FUT-004',absint($reel['id']),20,$reel);$related=self::safe_edges('F11-FUT-003',absint($reel['id']),12,$reel);$chapters=self::safe_edges('F11-FUT-017',absint($reel['id']),30,$reel,false);$cards=self::safe_objects('F11-FUT-018',absint($reel['id']),1,$reel);$transcripts=self::safe_objects('F11-FUT-016',absint($reel['id']),1,$reel);if(!$citations&&!$related&&!$chapters&&!$cards&&!$transcripts)return'';$html='<details class="rsv-future30-tools"><summary>'.esc_html__('Study & knowledge tools',RSV_TEXT_DOMAIN).'</summary>';if($citations){$html.='<h3>'.esc_html__('Timestamp sources',RSV_TEXT_DOMAIN).'</h3><ul>';foreach($citations as$row)$html.='<li>'.esc_html(gmdate('i:s',absint($row['start_second']))).' — '.esc_html($row['target_owner'].' · '.$row['target_ref']).'</li>';$html.='</ul>';}if($chapters){$html.='<h3>'.esc_html__('Key moments',RSV_TEXT_DOMAIN).'</h3><ol>';foreach($chapters as$row)$html.='<li>'.esc_html(gmdate('i:s',absint($row['start_second']))).' — '.esc_html($row['payload']['title']??__('Chapter',RSV_TEXT_DOMAIN)).'</li>';$html.='</ol>';}if($related){$html.='<h3>'.esc_html__('Related knowledge',RSV_TEXT_DOMAIN).'</h3><ul>';foreach($related as$row)$html.='<li>'.esc_html($row['target_owner'].' · '.$row['target_ref']).'</li>';$html.='</ul>';}if(!empty($cards[0]['payload']['summary']))$html.='<p class="rsv-knowledge-summary">'.esc_html($cards[0]['payload']['summary']).'</p>';if(!empty($transcripts[0]['payload']['transcript_ref']))$html.='<p class="rsv-transcript-reference"><strong>'.esc_html__('Reviewed transcript:',RSV_TEXT_DOMAIN).'</strong> '.esc_html($transcripts[0]['payload']['transcript_ref']).'</p>';return$html.'</details>';}
	private static function safe_edges( $feature,$reel_id,$limit,$reel,$validate_target=true ){global$wpdb;$table=RSV_Helpers::table('future_edges');$rows=$wpdb->get_results($wpdb->prepare("SELECT public_id,edge_type,target_owner,target_ref,start_second,end_second,payload_json FROM $table WHERE feature_id=%s AND source_reel_id=%d AND status=%s ORDER BY start_second ASC,id ASC LIMIT %d",$feature,$reel_id,'active',min(100,max(1,absint($limit)))),ARRAY_A);$out=array();foreach((array)$rows as$row){$row['payload']=RSV_Helpers::json_decode($row['payload_json']);unset($row['payload_json']);$owner=RSV_Helpers::text($row['target_owner']??'',30);$ref=RSV_Helpers::text($row['target_ref']??'',255);if($validate_target&&!self::public_ref_valid($owner,$ref,'public-tools-current'))continue;if('F11-FUT-004'===$feature&&(!$owner||!$ref))continue;if('F11-FUT-017'===$feature){$duration=absint(RSV_Repository::public_dto($reel)['duration_seconds']??0);if(absint($row['start_second'])>$duration||absint($row['end_second'])>$duration)continue;}$out[]=$row;}return$out;}
	private static function safe_objects( $feature,$reel_id,$limit,$reel ){global$wpdb;$table=RSV_Helpers::table('future_objects');$rows=$wpdb->get_results($wpdb->prepare("SELECT public_id,title,payload_json FROM $table WHERE feature_id=%s AND reel_id=%d AND status=%s ORDER BY updated_at DESC,id DESC LIMIT %d",$feature,$reel_id,'active',min(20,max(1,absint($limit)))),ARRAY_A);$out=array();foreach((array)$rows as$row){$p=RSV_Helpers::json_decode($row['payload_json']);if('F11-FUT-016'===$feature){$ref=RSV_Helpers::text($p['transcript_ref']??'',255);if(empty($p['reviewed'])||!$ref||true!==apply_filters('rsv_future30_transcript_ref_public_valid',false,$ref,$reel))continue;}if('F11-FUT-018'===$feature){$refs=array_merge((array)($p['remedy_refs']??array()),(array)($p['disease_refs']??array()),(array)($p['book_refs']??array()),(array)($p['source_refs']??array()));$valid=true;foreach($refs as$ref)if(!self::public_ref_valid('File 06',RSV_Helpers::text($ref,255),'knowledge-card-current')){$valid=false;break;}if(!$valid)continue;}$out[]=array('public_id'=>RSV_Helpers::text($row['public_id']??'',80),'title'=>RSV_Helpers::text($row['title']??'',255),'payload'=>self::safe_public_payload($p));}return$out;}
	private static function safe_file06_objects( $rows,$purpose ){$out=array();foreach($rows as$row){if(!is_array($row))continue;$p=(array)($row['payload']??array());$refs=array_merge((array)($p['source_refs']??array()),(array)($p['remedy_refs']??array()),(array)($p['disease_refs']??array()),(array)($p['book_refs']??array()));$valid=true;foreach($refs as$ref)if(!self::public_ref_valid('File 06',RSV_Helpers::text($ref,255),$purpose)){$valid=false;break;}if(!$valid)continue;$out[]=array('public_id'=>RSV_Helpers::text($row['public_id']??'',80),'title'=>RSV_Helpers::text($row['title']??'',255),'payload'=>self::safe_public_payload($p),'version'=>absint($row['version']??0),'updated_at'=>RSV_Helpers::text($row['updated_at']??'',40));}return$out;}
	private static function safe_public_payload( $payload ){$payload=is_array($payload)?$payload:array();$out=array();foreach($payload as$key=>$value){$key=sanitize_key($key);if(in_array($key,array('correct','answer','explanation_private','attestation_ref','notes','creator_voice_consent'),true))continue;if(is_array($value))$out[$key]=array_slice($value,0,100,true);elseif(is_bool($value)||is_numeric($value))$out[$key]=$value;else$out[$key]=RSV_Helpers::text($value,2000);}return$out;}
	private static function public_ref_valid( $owner,$ref,$purpose ){$owner=RSV_Helpers::text($owner,30);$ref=RSV_Helpers::text($ref,255);if(!$owner||!$ref)return false;if('File 11'===$owner){$target=RSV_Repository::find($ref,true);return(bool)($target&&RSV_Security::can_view_reel($target,0));}return true===apply_filters('rsv_future30_public_ref_valid',false,$owner,$ref,sanitize_key($purpose));}
	private static function raw_edge_payload( $public_id ){if(!$public_id)return array();global$wpdb;$table=RSV_Helpers::table('future_edges');$json=$wpdb->get_var($wpdb->prepare("SELECT payload_json FROM $table WHERE public_id=%s AND status=%s LIMIT 1",$public_id,'active'));return$json?(array)RSV_Helpers::json_decode($json,array()):array();}
	private static function latest_future_object( $feature,$reel_id ){global$wpdb;$table=RSV_Helpers::table('future_objects');$row=$wpdb->get_row($wpdb->prepare("SELECT public_id,title,payload_json,version,updated_at FROM $table WHERE feature_id=%s AND reel_id=%d AND status=%s ORDER BY updated_at DESC,id DESC LIMIT 1",$feature,absint($reel_id),'active'),ARRAY_A);if(!$row)return null;$row['payload']=RSV_Helpers::json_decode($row['payload_json']);unset($row['payload_json']);return$row;}
	private static function future_user_payload( $user_id,$feature,$object_ref,$state_key,$defaults ){global$wpdb;$table=RSV_Helpers::table('future_user_state');$json=$wpdb->get_var($wpdb->prepare("SELECT payload_json FROM $table WHERE user_id=%d AND feature_id=%s AND object_ref=%s AND state_key=%s LIMIT 1",absint($user_id),$feature,$object_ref,$state_key));return$json?array_merge((array)$defaults,(array)RSV_Helpers::json_decode($json,$defaults)):(array)$defaults;}
	private static function canonical_history_paused( $user_id ){global$wpdb;$table=RSV_Helpers::table('preferences');return(bool)$wpdb->get_var($wpdb->prepare("SELECT history_paused FROM $table WHERE user_id=%d LIMIT 1",absint($user_id)));}
	private static function collection_key( $supplied,$name ){$supplied=trim((string)$supplied);if($supplied&&preg_match('/^[a-z0-9][a-z0-9_-]{0,59}$/',$supplied))return$supplied;return'collection_'.substr(hash('sha256',strtolower($name)),0,24);}
